/**
 * @event
 * @name scwin.grd_formFileList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_formFileList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_formFileList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_formFileList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (String(r["requiredYn"]) === "Y") { if (typeof scwin.editAttach === 'function') { scwin.editAttach("this"); } else { console.error('[sdd] 행 동작 미정의: scwin.editAttach (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.editAttach'); } return; }
        if (String(r["requiredYn"]) === "Y") { if (typeof scwin.isNotRelated === 'function') { scwin.isNotRelated("this"); } else { console.error('[sdd] 행 동작 미정의: scwin.isNotRelated (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.isNotRelated'); } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formFileList.oncellclick' });
    }
};

