        const editObj = document.getElementsByName('editYn');
        await moveUrl(url, {});
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkFileValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx
 * @returns
 * @hidden N
*/
scwin.checkFileValue = async function (idx) {
    /* sdd-asis-lifecycle:begin checkFileValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkObj = document.getElementsByName('useYn');
    const itemObj = document.getElementsByName('fileItmNm');
    let fileObj;
    let itmVal;
    if (chkObj[idx].checked !== true) {
        fileObj = form['attachFiles['+idx+']'];
        if (fileObj.value === '') {
            itmVal = itemObj[idx].value;
            itmVal = (itmVal === '' ? '기타' : itmVal);
            await $c.win.alert("[" + itmVal + ']항목에 대한 해당사항이 없는경우 해당사항 없음을 체크하십시오.');
            return false;
        }
        if (idx >= $) {
            fn: length(formFileList);
        }
        if (itemObj[idx].value === '') {
            await $c.win.alert("기타 첨부서류가 있는 경우 '항목명'까지 작성하셔야 합니다.");
            return false;
        }
        return true;
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkFileYN
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkFileYN = async function () {
    /* sdd-asis-lifecycle:begin checkFileYN — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkObj = document.getElementsByName('useYn');
    const editObj = document.getElementsByName('editYn');
    if (loadTp == 2 || loadTp == 3) {
        for (var i = 0; i < chkObj.length; i++) {
            if (editObj[i].checked === true) {
                if (!await scwin.checkFileValue(i)) {
                    return false;
                }
            }
        }
    } else {
        for (var i = 0; i < chkObj.length; i++) {
            if (!await scwin.checkFileValue(i)) {
                return false;
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCBoxTrue
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.setCBoxTrue = function (ver) {
    /* sdd-asis-lifecycle:begin setCBoxTrue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkObj = document.getElementsByName(ver);
    let tORf = true;
    if (ver === 'editYn') {
        tORf = false;
    }
    for (let i = 0; i < chkObj.length; i++) {
        if (chkObj[i].checked === tORf) {
            chkObj[i].value = 'N';
        } else {
            chkObj[i].value = 'Y';
        }
        chkObj[i].checked = true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkValue = async function () {
    /* sdd-asis-lifecycle:begin checkValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await scwin.checkFileYN()) {
        scwin.setCBoxTrue('useYn');
        if (loadTp == 2 || loadTp == 3) {
            scwin.setCBoxTrue('editYn');
        }
        return true;
    } else {
        return false;
    }
    /* sdd-asis-lifecycle:end */
};


