/**
 * @method
 * @name scwin.getObjIdx
 * @author Inswave
 * @date 2026. 09. 29
 * @param tmpObj ver
 * @returns
 * @hidden N
*/
scwin.getObjIdx = function (tmpObj, ver) {
    /* sdd-asis-lifecycle:begin getObjIdx — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let idx;
    const chkObj = document.getElementsByName(ver);
    for (let i = 0; i < chkObj.length; i++) {
        if (chkObj[i] === '[object]') {
            if (chkObj[i] === tmpObj) {
                idx = i;
                break;
            }
        }
    }
    return idx;
    /* sdd-asis-lifecycle:end */
};


